quilt-canvas-tui-main/bridge/chiaroscuro:
// bridge/chiaroscuro.mjs — L4 feed renderer for quilt-canvas.
// Port of SuperInstance/chiaroscuro's engine contracts (README §6) onto the
// quilt fabric as substrate. Per-cell decision procedure, deterministic,
// zero deps. A rendered frame is a receipt of the fabric state.
//
// Engine input contracts (from the chiaroscuro README):
//   glyph  — brightness (one value per cell) → tone ramp
//   sculpt — brightness + edge magnitude → box-drawing slope glyphs
// The fabric provides: dials (→ tone), links (→ edge structure).

export const RAMP10 = " .:-=+*#%@"; // 1970s teletype ramp, the README's historical default
export const EDGE_LIGHT = ["─", "╱", "│", "╲"]; // 4 cardinal slopes by angle quadrant
export const EDGE_HEAVY = ["═", "╱", "║", "╲"]; // high-magnitude variants

// ramp(v, rampStr): normalized 0..1 → glyph. Fail-closed: empty ramp → "�",
// out-of-range clamps. Never throws on bad input (canvas keeps rendering).
export function ramp(v, rampStr = RAMP10) {
  if (!rampStr || rampStr.length === 0) return "�";
  if (!(v > 0)) return rampStr[0]; // covers NaN, negatives
  if (v >= 1) return rampStr[rampStr.length - 1];
  return rampStr[Math.floor(v * (rampStr.length - 1))];
}

// cellTone(cell, dialCap): normalized brightness from a fabric cell's dials.
// Empty dials → 0 (blank paper). Deterministic.
export function cellTone(cell, dialCap = 255) {
  const d = cell?.dials;
  if (!Array.isArray(d) || d.length === 0) return 0;
  let m = 0;
  for (const x of d) { const v = Math.abs(x); if (v > m) m = v; }
  return Math.min(1, m / dialCap);
}

// cellEdge(cell): magnitude (0..) and a direction index 0..3 from link
// geometry. Direction: count links going to column-neighbors as horizontal,
// row-neighbors as vertical; the dominant axis picks the glyph family.
// This is a cheap stand-in for Sobel on a grid — documented, not claimed
// to be image Sobel.
export function cellEdge(cell, allCells = []) {
  const links = Array.isArray(cell?.links) ? cell.links : [];
  const mag = links.length;
  if (mag === 0) return { mag: 0, dir: 0 };
  const byId = new Map(allCells.map((c) => [c.id, c]));
  let horiz = 0, vert = 0;
  for (const id of links) {
    const t = byId.get(id);
    if (!t) continue;
    const [fc, fr] = splitId(cell.id);
    const [tc, tr] = splitId(t.id);
    if (tc !== fc) horiz++;
    if (tr !== fr) vert++;
  }
  // dir: 0 = horizontal face, 2 = vertical wall; diagonal when tied & both present
  if (horiz > 0 && vert > 0) return { mag, dir: horiz >= vert ? 0 : 2 };
  if (horiz > 0) return { mag, dir: 0 };
  return { mag, dir: 2 };
}

function splitId(id) {
  const m = /^([A-Z]+)([0-9]+)$/.exec(String(id ?? ""));
  if (!m) return [0, 0];
  let col = 0;
  for (const ch of m[1]) col = col * 26 + (ch.charCodeAt(0) - 64);
  return [col, parseInt(m[2], 10)];
}

// renderGrid(fabric, opts): fabric {tick, cells, links} → text grid.
// opts: {cols, rows, engine: "glyph"|"sculpt", dialCap}
// FAIL-closed on unknown engine: first row is "ERR:<engine>" and the rest
// is blank — the renderer reports, never crashes (canvas stays alive).
export function renderGrid(fabric, opts = {}) {
  const cols = opts.cols ?? 8;
  const rows = opts.rows ?? 4;
  const engine = opts.engine ?? "glyph";
  const cap = opts.dialCap ?? 255;
  if (engine !== "glyph" && engine !== "sculpt") {
    // Never truncate the error prefix — a fail-closed row must stay
    // readable at any grid width (the row may exceed cols by design).
    const blank = " ".repeat(cols);
    return [`ERR:${engine}`.padEnd(cols, " "), ...Array(rows - 1).fill(blank)].join("\n");
  }
  const cells = Array.isArray(fabric?.cells) ? fabric.cells : [];
  const grid = [];
  for (let r = 1; r <= rows; r++) {
    let line = "";
    for (let c = 1; c <= cols; c++) {
      const id = colName(c) + r;
      const cell = cells.find((x) => x.id === id);
      const tone = cellTone(cell, cap);
      if (engine === "glyph") {
        line += ramp(tone, opts.ramp ?? RAMP10);
      } else {
        // sculpt: edge overrides tone when magnitude ≥ threshold (README:
        // edgeMix — "how much of the edge glyph should override the tone")
        const edge = cellEdge(cell, cells);
        const thresh = opts.edgeThreshold ?? 1;
        if (edge.mag >= thresh) {
          const heavy = edge.mag >= (opts.heavyAt ?? 2);
          const set = heavy ? EDGE_HEAVY : EDGE_LIGHT;
          line += set[edge.dir] ?? set[0];
        } else {
          line += ramp(tone, opts.ramp ?? RAMP10);
        }
      }
    }
    grid.push(line);
  }
  return grid.join("\n");
}

function colName(n) {
  let s = "";
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s || "A";
}

quilt-canvas-tui-main/bridge/test_chiaro:
// FAIL-first pins for bridge/chiaroscuro.mjs — the L4 feed renderer.
// Model: chiaroscuro engines are per-cell decision procedures over a
// substrate. Our substrate = the quilt fabric. Each fabric cell contributes
// a normalized "tone" (0..1) and optionally an "edge" magnitude+direction.
// Engine contracts follow SuperInstance/chiaroscuro README §6:
//   glyph:  brightness → 70-step Fine ramp (we use the classic 10-step
//           for terminal fidelity, Fine is browser-only by design)
//   sculpt: brightness + edge magnitude → box-drawing slope glyphs
// Receipt discipline: deterministic, no deps, no timers.
import { test } from "node:test";
import assert from "node:assert/strict";
import { createRequire } from "node:module";

const RAMP10 = " .:-=+*#%@";

test("ramp: 0 → lightest glyph, 1 → darkest, monotone non-decreasing", async () => {
  const { ramp } = await importFresh();
  assert.equal(ramp(0, RAMP10), " ");
  assert.equal(ramp(1, RAMP10), "@");
  let prev = -1;
  for (let i = 0; i <= 20; i++) {
    const idx = RAMP10.indexOf(ramp(i / 20, RAMP10));
    assert.ok(idx >= prev, `monotone at i=${i}`);
    prev = idx;
  }
});

test("ramp: clamps out-of-range and empty ramp fails closed", async () => {
  const { ramp } = await importFresh();
  assert.equal(ramp(-5, RAMP10), " ");
  assert.equal(ramp(99, RAMP10), "@");
  assert.equal(ramp(0.5, ""), "�"); // fail-closed glyph, not a throw
});

test("renderGrid: tone from dials — cell heat = max dial normalized", async () => {
  const { renderGrid } = await importFresh();
  // fabric: 2x2. A1 dials [8,0] → heat 8/255; B1 empty → heat 0; etc.
  const fabric = {
    tick: 1,
    cells: [
      { id: "A1", version: 2, dials: [8, 0],   formula: null, kind: "generic", reads: [], links: [] },
      { id: "B1", version: 1, dials: [255, 0], formula: null, kind: "generic", reads: [], links: [] },
      { id: "A2", version: 1, dials: [],       formula: null, kind: "generic", reads: [], links: [] },
      { id: "B2", version: 3, dials: [128],    formula: null, kind: "generic", reads: [], links: [] },
    ],
    links: [],
  };
  const grid = renderGrid(fabric, { cols: 2, rows: 2, engine: "glyph", dialCap: 255 });
  const lines = grid.split("\n");
  assert.equal(lines.length, 2);
  // B1 (255) must be strictly darker than A1 (8)
  const dark = (ch) => RAMP10.indexOf(ch);
  assert.ok(dark(lines[0][1]) > dark(lines[0][0]));
  // A2 empty → lightest
  assert.equal(lines[1][0], " ");
  // B2 (128) mid-tone, darker than A1(8)? 128/255≈0.5 → idx 5; 8/255→idx 0
  assert.ok(dark(lines[1][1]) > dark(lines[0][0]));
});

test("renderGrid: sculpt engine — linked cells render as edges (─/│/┌), magnitude from link count", async () => {
  const { renderGrid } = await importFresh();
  const fabric = {
    tick: 1,
    cells: [
      { id: "A1", version: 2, dials: [100], formula: null, kind: "generic", reads: [], links: ["B1", "A2"] },
      { id: "B1", version: 1, dials: [100], formula: null, kind: "generic", reads: [], links: ["A1"] },
      { id: "A2", version: 1, dials: [100], formula: null, kind: "generic", reads: [], links: ["A1"] },
      { id: "B2", version: 1, dials: [100], formula: null, kind: "generic", reads: [], links: [] },
    ],
    links: [["A1", "B1"], ["A1", "A2"]],
  };
  const grid = renderGrid(fabric, { cols: 2, rows: 2, engine: "sculpt", dialCap: 255 });
  const EDGE = new Set("─│┌┐└┴┬├┤╋╱╲═║╔╗╚╠╦╬");
  // A1 has 2 links (high magnitude) → edge glyph; B2 has none → tone glyph
  assert.ok(EDGE.has(grid.split("\n")[0][0]), "A1 should render as edge");
  assert.ok(!EDGE.has(grid.split("\n")[1][1]), "B2 should render as tone");
});

test("renderGrid: unknown engine fails closed with error row, not a throw", async () => {
  const { renderGrid } = await importFresh();
  const grid = renderGrid({ tick: 0, cells: [], links: [] }, { cols: 2, rows: 1, engine: "nonsense" });
  assert.match(grid, /ERR/);
});

test("renderGrid: determinism — same fabric, same bytes", async () => {
  const { renderGrid } = await importFresh();
  const fabric = {
    tick: 7,
    cells: [
      { id: "A1", version: 9, dials: [1, 2, 3], formula: "sum A1,B1", kind: "sum", reads: ["A1", "B1"], links: ["B1"] },
      { id: "B1", version: 1, dials: [4], formula: null, kind: "generic", reads: [], links: ["A1"] },
    ],
    links: [["A1", "B1"]],
  };
  const a = renderGrid(fabric, { cols: 2, rows: 1, engine: "sculpt" });
  const b = renderGrid(fabric, { cols: 2, rows: 1, engine: "sculpt" });
  assert.equal(a, b);
});

async function importFresh() {
  // isolate module state per test file run
  const require = createRequire(import.meta.url);
  const mod = "./chiaroscuro.mjs";
  const resolved = require.resolve(mod);
  const q = `?t=${Date.now()}-${Math.random()}`;
  return await import(resolved + q);
}
